/*
 * COMPOSITION: A single full-bleed editorial plate (7x5.5 @ z=0) carries a
 *   vertical ink->surface gradient with fine grain; kicker/hero/rule/body/
 *   caption sit left-aligned on a strict baseline grid slightly in front
 *   (z=0.01), with letterpress duplicate hero glyphs at z=-0.02 for depth.
 * LIGHT RIG: rig-dusk-editorial — warm directional key (2.8) + warm point
 *   fill (3) + cool directional rim (1.7) + 0.09 ambient floor, positions
 *   scaled to the plate's bounding radius.
 * MATERIAL STRATEGY: matte MeshStandardNodeMaterial plate (roughness 0.85,
 *   metalness 0) driven by a TSL gradient+grain colorNode; the signal-red
 *   underline rule is a small emissive MeshStandardNodeMaterial slab
 *   (emissiveIntensity 1.2, capped under 2.3).
 * MOTION: rise-in per text block (y+0.4->0, opacity 0->1, 700ms power3-ish,
 *   80ms stagger, top-to-bottom) then the accent rule draws scaleX 0->1
 *   over 500ms once the hero has landed; idle state has no perpetual motion.
 * FOCAL ELEMENT: the two-line hero headline "PRECISION IS / A HABIT." is the
 *   single brightest, largest element — everything else graded beneath it.
 */

import {
  MeshStandardNodeMaterial,
  DirectionalLight,
  PointLight,
  AmbientLight,
  PlaneGeometry,
  Group,
} from 'three/webgpu';
import { uv, mix, color, sin, fract } from 'three/tsl';
import { gsap } from 'gsap';

const PX_TO_SCENE = 1 / 200; // matches typography token scale (124px -> 0.62 units)

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  root.name = 'nova-editorial-headline';

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role, idx = 0) => items.filter((i) => i.role === role)[idx];

  const kicker = byRole('kicker', 0) ?? { text: 'NOVA ATELIER / JOURNAL' };
  const heroLine1 = byRole('hero', 0) ?? { text: 'PRECISION IS' };
  const heroLine2 = byRole('hero', 1) ?? { text: 'A HABIT.' };
  const body = byRole('body', 0) ?? { text: '' };
  const caption = byRole('caption', 0) ?? { text: '' };

  const disposables = { geometries: [], materials: [], textObjects: [] };
  const timelines = [];

  // ---------------------------------------------------------------------
  // BACKDROP PLATE — vertical engineered gradient + subtle grain (TSL)
  // ---------------------------------------------------------------------
  const plateGeo = new PlaneGeometry(7, 5.5);
  const plateMat = new MeshStandardNodeMaterial({ roughness: 0.85, metalness: 0.0 });

  const uvNode = uv();
  const gradient = mix(color(colors.background), color(colors.surface), uvNode.y);
  const hash = fract(
    sin(uvNode.x.mul(12.9898).add(uvNode.y.mul(78.233))).mul(43758.5453)
  );
  const grain = hash.sub(0.5).mul(0.015);
  plateMat.colorNode = gradient.add(grain);

  const plate = new THREE.Mesh(plateGeo, plateMat);
  plate.position.set(0, 0, 0);
  root.add(plate);
  disposables.geometries.push(plateGeo);
  disposables.materials.push(plateMat);

  // ---------------------------------------------------------------------
  // LIGHT RIG — rig-dusk-editorial, subject-relative positions scaled
  // ---------------------------------------------------------------------
  const radius = 3.5;
  const ambient = new AmbientLight(0xffffff, 0.09);
  root.add(ambient);

  const key = new DirectionalLight(0xffc890, 2.8);
  key.position.set(3 * radius, 0.9 * radius, 1.2 * radius);
  key.target.position.set(0, 0.4, 0);
  root.add(key, key.target);

  const fill = new PointLight(0xb9a68e, 3, 9, 2);
  fill.position.set(-2.4 * radius, 0.6 * radius, 1.8 * radius);
  root.add(fill);

  const rim = new DirectionalLight(0xf2f4f6, 1.7);
  rim.position.set(-1.8 * radius, 2.8 * radius, -2 * radius);
  rim.target.position.set(0, 0.6, 0);
  root.add(rim, rim.target);

  // ---------------------------------------------------------------------
  // TYPE — strict baseline grid, left aligned at x=-3.1
  // ---------------------------------------------------------------------
  const X = -3.1;

  function makeText(str, opts, pos) {
    const obj = ctx.fontAtlas.createText(str, opts);
    obj.position.set(pos[0], pos[1], pos[2]);
    root.add(obj);
    disposables.textObjects.push(obj);
    return obj;
  }

  const kickerObj = makeText(
    kicker.text,
    { fontSize: 18, color: colors.paper, align: 'left', letterSpacingPx: 0.12 * 18 },
    [X, 1.7, 0.01]
  );

  // letterpress shadow duplicates for the hero lines (ink, 0.02 units behind)
  const heroShadow1 = makeText(
    heroLine1.text,
    { fontSize: 124, color: colors.ink, align: 'left', letterSpacingPx: -0.015 * 124 },
    [X, 0.9, -0.02]
  );
  const heroShadow2 = makeText(
    heroLine2.text,
    { fontSize: 124, color: colors.ink, align: 'left', letterSpacingPx: -0.015 * 124 },
    [X, 0.25, -0.02]
  );

  const heroObj1 = makeText(
    heroLine1.text,
    { fontSize: 124, color: colors.paper, align: 'left', letterSpacingPx: -0.015 * 124 },
    [X, 0.9, 0.01]
  );
  const heroObj2 = makeText(
    heroLine2.text,
    { fontSize: 124, color: colors.paper, align: 'left', letterSpacingPx: -0.015 * 124 },
    [X, 0.25, 0.01]
  );

  const bodyObj = makeText(
    body.text,
    {
      fontSize: 26,
      color: colors.paper,
      align: 'left',
      maxWidthPx: 4.5 / PX_TO_SCENE,
      letterSpacingPx: 0,
    },
    [X, -0.8, 0.01]
  );

  const captionObj = makeText(
    caption.text,
    { fontSize: 18, color: colors.paper, align: 'left', letterSpacingPx: 0.08 * 18 },
    [X, -1.9, 0.01]
  );

  // ---------------------------------------------------------------------
  // ACCENT UNDERLINE RULE — signal red, emissive, drawn after hero lands
  // ---------------------------------------------------------------------
  const ruleGeo = new PlaneGeometry(2.2, 0.05);
  const ruleMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.accent),
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 1.2,
    roughness: 0.5,
    metalness: 0.1,
  });
  const rule = new THREE.Mesh(ruleGeo, ruleMat);
  rule.position.set(X + 2.2 / 2, -0.15, 0.01);
  rule.scale.x = 0.0001;
  root.add(rule);
  disposables.geometries.push(ruleGeo);
  disposables.materials.push(ruleMat);

  // ---------------------------------------------------------------------
  // MOTION — rise-in per block, top-to-bottom, 80ms stagger, then rule draw
  // ---------------------------------------------------------------------
  const blocks = [
    kickerObj,
    [heroShadow1, heroObj1],
    [heroShadow2, heroObj2],
    bodyObj,
    captionObj,
  ];

  const tl = gsap.timeline();
  blocks.forEach((blockEntry, i) => {
    const group = Array.isArray(blockEntry) ? blockEntry : [blockEntry];
    group.forEach((obj) => {
      const targetY = obj.position.y;
      obj.position.y = targetY + 0.4;
      obj.visible = true;
      if (obj.material) {
        obj.traverse?.((c) => {
          if (c.material) c.material.transparent = true;
        });
      }
      const opacityHolder = { o: 0 };
      tl.to(
        obj.position,
        { y: targetY, duration: 0.7, ease: 'power3.out' },
        i * 0.08
      );
      tl.to(
        opacityHolder,
        {
          o: 1,
          duration: 0.7,
          ease: 'power2.out',
          onUpdate: () => {
            obj.traverse?.((c) => {
              if (c.material) {
                c.material.opacity = opacityHolder.o;
                c.material.needsUpdate = true;
              }
            });
          },
        },
        i * 0.08
      );
    });
  });

  tl.to(
    rule.scale,
    { x: 1, duration: 0.5, ease: 'power2.out' },
    blocks.length * 0.08 + 0.1
  );
  timelines.push(tl);

  // ---------------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    disposables.geometries.forEach((g) => g.dispose());
    disposables.materials.forEach((m) => m.dispose());
    disposables.textObjects.forEach((obj) => {
      obj.traverse?.((c) => {
        c.geometry?.dispose?.();
        if (c.material) {
          if (Array.isArray(c.material)) c.material.forEach((m) => m.dispose());
          else c.material.dispose();
        }
      });
    });
    plate.geometry.dispose();
    plateMat.dispose();
    rule.geometry.dispose();
    ruleMat.dispose();
  };

  return root;
}

/* @spec-manifest
{"elements":[
  {"id":"text.kicker.0","where":"createNode:kickerObj","how":"ctx.fontAtlas.createText kicker copy at y=1.7"},
  {"id":"text.hero.1","where":"createNode:heroObj1/heroShadow1","how":"hero line1 text plus letterpress shadow dup"},
  {"id":"text.hero.2","where":"createNode:heroObj2/heroShadow2","how":"hero line2 text plus letterpress shadow dup"},
  {"id":"text.body.3","where":"createNode:bodyObj","how":"body paragraph createText maxWidthPx 4.5 units"},
  {"id":"text.caption.4","where":"createNode:captionObj","how":"caption createText at y=-1.9"},
  {"id":"color.background","where":"createNode:gradient","how":"colors.background used as gradient stop 0"},
  {"id":"color.surface","where":"createNode:gradient","how":"colors.surface used as gradient stop 1"},
  {"id":"color.ink","where":"createNode:heroShadow1/heroShadow2","how":"ink color on letterpress shadow glyphs"},
  {"id":"color.paper","where":"createNode:makeText calls","how":"paper color applied to all readable text"},
  {"id":"color.accent","where":"createNode:ruleMat","how":"accent color + emissive on underline rule mesh"},
  {"id":"color.gradient","where":"createNode:plateMat.colorNode","how":"TSL mix(background,surface,uv.y) gradient"},
  {"id":"effects.spec","where":"createNode:plateMat/hash/grain","how":"7x5.5 plate, gradient, grain, letterpress, rule draw"}
]}
*/
